INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-07', 'INSURANCE', '종합위험 수확감소보장방식', '16종 작물(포도·복숭아·자두·감귤만감류·밤·호두·참다래·대추·매실·살구·오미자·유자·사과·배·단감·떫은감)을 대상. 보험기간 동안 보장하는 재해로 인한 수확량 감소를 보장. 시기별 조사: 예찰조사 / 피해사실 확인조사 / (작물별) 수확량조사 / 비가림시설 손해조사. 보험금 = 보험가입금액 × (피해율 - 자기부담비율). 피해율 = (평년수확량-수확량-미보상감수량)÷평년수확량.', '종합위험 수확감소보장', NULL, NULL, 'p.428', 428, 435, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-08', 'INSURANCE', '종합위험 과실손해보장방식', '4종 작물(감귤(온주밀감류)·오디·두릅·블루베리)을 대상. 보험기간 동안 보장하는 재해로 과실손해가 발생하여 이로 인한 수확량감소를 보장하는 방식. 작물별 보험금 산정 별도(오디=수확량 기반 피해율 / 감귤 온주밀감=손해액 기반 / 두릅=정아지수 / 블루베리=재배종별 가중 + 꽃 피해 보정).', '종합위험 과실손해보장', NULL, NULL, 'p.468', 468, 475, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-09', 'INSURANCE', '수확전 종합위험 과실손해보장방식', '2종 작물(복분자·무화과)을 대상. 보험기간 개시일~수확개시 이전: 자연재해·조수해·화재 종합위험 / 수확개시 이후~수확종료: 태풍(강풍)·우박 특정위험. 복분자 식물체 피해율 65% 이상 시 경작불능보험금 지급 가능 분기. 시기별 조사: 피해사실 확인조사 / 경작불능조사(복분자) / (종합위험)과실손해조사 / (특정위험)과실손해조사 / 고사나무조사.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.486', 486, 493, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-10', 'INSURANCE', '수확량감소 추가보장 특약', '포도·복숭아·감귤(만감류) 대상 특약. 보장재해로 피해율이 자기부담비율을 초과하는 경우 적용. 보험금 = 보험가입금액 × (피해율 × 10%). 주계약(F-14)과 별도 산정 후 합산 지급.', '종합위험 수확감소보장', NULL, NULL, 'p.465', 465, 472, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-11', 'INSURANCE', '나무손해보장 특별약관', '수확감소·과실손해 보장 작물에 부가하는 나무 단위 보장 특약. 보험금 = 보험가입금액 × (피해율 - 자기부담비율). 피해율 = 피해주수(수확전+수확완료 후 고사주수 합, 미보상고사주수 제외) ÷ 실제결과주수. 감귤 온주밀감의 자기부담비율은 5% 고정.', '나무손해보장', NULL, NULL, 'p.465', 465, 472, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-12', 'INSURANCE', '종합위험 비가림시설 손해보장방식', '포도·참다래·대추 대상 비가림시설 단위 보장. 보험금 = MIN(손해액 - 자기부담금, 보험가입금액). 자기부담금 = 손해액의 10%(본체 30만~100만 한도 / 피복재 단독 10만~30만 한도). 화재 손해는 자기부담금 미적용. 손해 발생 후 180일 이내 수리·복구 의사 서면 통지 의무.', '비가림시설 손해보장', NULL, NULL, 'p.465', 465, 472, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-13', 'INSURANCE', '수확개시 이후 동상해보장 특별약관', '감귤(온주밀감류) 대상. 보험기간 내 동상해로 인한 손해액이 자기부담금을 초과하는 경우 동상해 손해보험금 지급. 손해액 = {보험가입금액 - (보험가입금액×기사고피해율)} × 수확기잔존비율 × 동상해피해율 × (1 - 미보상비율). 수확기잔존비율은 12월/1월/2월별 사고발생일자 함수.', '수확개시 이후 동상해보장', NULL, NULL, 'p.483', 483, 490, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INS-14', 'INSURANCE', '과실손해 추가보장 특별약관', '감귤(온주밀감류) 대상. 보장재해로 손해액이 자기부담금을 초과하는 손해 발생 시 적용. 보험금 = 보험가입금액 × 주계약 피해율 × 10%. 주계약 피해율은 과실손해보장(보통약관)에서 산출한 피해율.', '과실손해 추가보장', NULL, NULL, 'p.485', 485, 492, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-005', 'CROP', '포도', '종합위험 수확감소보장방식 16종 중 1. 비가림시설 손해보장 적용 작물 (참다래·대추와 함께). 수확량감소 추가보장 특약 적용 가능. 수확량조사 = 착과수조사 → 과중조사 → 수확량 산정.', '종합위험 수확감소보장', NULL, NULL, 'p.428', 428, 435, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-006', 'CROP', '복숭아', '종합위험 수확감소보장방식 16종 중 1. 병충해(세균구멍병) 보장 — 50%형 피해과실로 인정 (피해무게×0.5 = 병충해감수량). 수확량감소 추가보장 특약 적용. 피해율 산식 별도 (F-16).', '종합위험 수확감소보장', NULL, NULL, 'p.428', 428, 435, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-007', 'CROP', '자두', '종합위험 수확감소보장방식 16종 중 1. 착과수조사 적용 (포도·복숭아·자두·감귤만감류는 적과 종료 시점 착과수 조사 의무).', '종합위험 수확감소보장', NULL, NULL, 'p.428', 428, 435, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
