INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-013', 'CROP', '매실', '종합위험 수확감소보장방식 16종 중 1. 비대추정지수(별표4) 조사 의무 — 표본주 착과 무게 = 조사 착과량 × 비대추정지수 × 2(절반조사 시) (F-24).', '종합위험 수확감소보장', NULL, NULL, 'p.451', 451, 458, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-014', 'CROP', '살구', '종합위험 수확감소보장방식 16종 중 1. 피해인정계수 별표3 적용 (대추·매실·살구 동일).', '종합위험 수확감소보장', NULL, NULL, 'p.451', 451, 458, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-015', 'CROP', '오미자', '종합위험 수확감소보장방식 16종 중 1. 형태별·수령별 표본구간(유인틀 길이 1m 단위) 조사 — 다른 과수와 다른 표본 단위.', '종합위험 수확감소보장', NULL, NULL, 'p.455', 455, 462, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-016', 'CROP', '유자', '종합위험 수확감소보장방식 16종 중 1. 평년수확량 적용 시 산출값과 최근 7년간 과거 수확량 올림픽 평균값 중 더 큰 값 적용 (예외 규칙).', '종합위험 수확감소보장', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-017', 'CROP', '감귤(온주밀감류)', '종합위험 과실손해보장방식 4종 중 1. 손해액 기반 산정(F-27) + 등급 내/외 피해과실 분류(30%/50%/80%/100%형). 동상해 보장 특약(INS-13) + 나무손해보장 특약(자기부담비율 5% 고정) + 과실손해 추가보장 특약(INS-14) 적용 가능. 감귤(만감류, CROP-008)와 별도.', '종합위험 과실손해보장', NULL, NULL, 'p.468', 468, 475, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-018', 'CROP', '오디', '종합위험 과실손해보장방식 4종 중 1. 결실수 기반 피해율(F-26) — 평년결실수 / 조사결실수 / 미보상감수결실수 / 환산결실수(표본가지 결실수합÷표본가지 길이합) / 주당 평년결실수.', '종합위험 과실손해보장', NULL, NULL, 'p.480', 480, 487, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-019', 'CROP', '두릅', '종합위험 과실손해보장방식 4종 중 1. 정아지수 기반 피해율(F-29) = (피해 정아지수 ÷ 총 정아지수) × (1 - 미보상비율).', '종합위험 과실손해보장', NULL, NULL, 'p.473', 473, 480, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-020', 'CROP', '블루베리', '종합위험 과실손해보장방식 4종 중 1. 가장 복잡한 산식 — 꽃 피해조사 유무에 따라 분기. 꽃 피해 미실시 시 F-30 × (1-미보상비율). 꽃 피해 실시 시 F-31 (최종 꽃 피해율 + (1-최종꽃피해율)×F-30×(1-미보상비율)). 잔여수확량비율 = 수확개시 이전 1 / 이후 1-(사고일자-수확개시일자)/30.', '종합위험 과실손해보장', NULL, NULL, 'p.474', 474, 481, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-021', 'CROP', '복분자', '수확전 종합위험 과실손해보장방식 2종 중 1. 보험기간 분기 — 종합위험(계약일~가입 이듬해 5월 31일) / 특정위험(가입 이듬해 6월 1일~6월 20일). 식물체 피해율 65% 이상 시 경작불능보험금 지급 가능. 살아있는 결과모지수 + 수정불량(송이) 피해율 조사 (별표1 표본구간수표).', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.486', 486, 493, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CROP-022', 'CROP', '무화과', '수확전 종합위험 과실손해보장방식 2종 중 1. 보험기간 = 계약일~가입 이듬해 7월 31일. 수확직전 과실피해조사 + 수확시작 후 표본주의 고사·정상 결과지수 조사.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.491', 491, 498, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-016', 'INVESTIGATION', '종합위험 예찰조사', '재해발생 전부터 보험 품목에 대한 평가를 위한 생육조사. 농업재해보험 손해평가요령 제13조제4항 근거. 사고 여부와 관계없이 가입한 모든 과수원이 대상. 2026년 신설 조사 (BATCH-R1 정합).', '종합위험 수확감소보장', NULL, NULL, 'p.429', 429, 436, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-017', 'INVESTIGATION', '피해사실 확인조사 (종합위험)', '대상 재해로 사고 접수 농지 및 조사 필요 농지. 자연재해, 조수해, 화재, 병충해(복숭아 세균구멍병/사과 자연재해성 탄저병). 사고 접수 직후 실시. 피해사실 명백 시 생략 가능.', '종합위험 수확감소보장', NULL, NULL, 'p.429', 429, 436, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-018', 'INVESTIGATION', '착과수조사', '통상적인 적과 종료 시점 총 착과 수 조사. 대상: 포도·복숭아·자두·감귤만감류·사과·배·단감·떫은감 (수확 직전). 조사방법: 표본조사. 피해와 관계없이 전 과수원 조사.', '종합위험 수확감소보장', NULL, NULL, 'p.428', 428, 435, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-019', 'INVESTIGATION', '과중조사', '품종별 수확시기에 각각 실시. 표본주에서 평균적 착과량 3주 이상 + 품종별 20개 이상(농지당 60개 이상) 추출. 밤은 30mm 소과 분류 후 무게 80% 적용. 호두는 청피 개수 + 무게.', '종합위험 수확감소보장', NULL, NULL, 'p.432', 432, 439, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-020', 'INVESTIGATION', '착과피해 구성 조사', '착과피해를 유발하는 재해가 있을 경우 시행. 품종별 3개 이상 표본주에서 임의의 과실 20개 이상(품종별 20개, 농지당 60개 이상) 추출. 별표3 피해인정계수 적용 — 정상/30%형/50%형/80%형/100%형 분류.', '종합위험 수확감소보장', NULL, NULL, 'p.441', 441, 448, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-021', 'INVESTIGATION', '낙과피해조사', '착과수조사 이후 낙과피해 발생 농지. 사고 접수 직후 실시. 표본주별 수관면적 내 낙과수 조사. 표본주의 수관면적 내 낙과는 표본주와 품종이 다르더라도 해당 표본주 낙과로 본다.', '종합위험 수확감소보장', NULL, NULL, 'p.435', 435, 442, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-022', 'INVESTIGATION', '낙과수 전수조사', '표본조사가 불가할 경우 실시. 전체 낙과에 대한 품종 구분 가능 시 전체 낙과수를 품종별 산정. 품종 구분 어려울 시 100개 이상 표본 추출 후 비율 적용.', '종합위험 수확감소보장', NULL, NULL, 'p.436', 436, 443, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-023', 'INVESTIGATION', '수확 개시 전 수확량조사', '조사일 기준 농지 수확이 시작되기 전. 조기 수확 및 수확해태로 분쟁 시 지역 농업기술센터 등 농업 전문기관 판단. 표본주 선정 → 면적 → 착과수 → 과중 → 미보상비율 순.', '종합위험 수확감소보장', NULL, NULL, 'p.438', 438, 445, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-024', 'INVESTIGATION', '수확 개시 후 수확량조사', '조사일 기준 농지 수확이 시작된 후. 기수확량 조사 추가 — 사고 발생 전 수확된 수량. 수확 개시 후는 기수확량 + 잔여수확량 보정 산정.', '종합위험 수확감소보장', NULL, NULL, 'p.447', 447, 454, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-025', 'INVESTIGATION', '비대추정지수 조사 (매실)', '품종별 적정 수확 일자 및 조사 일자, 과실 비대추정지수 별표4 참조하여 조사. 조사 시점이 수확 시점보다 빠를 경우 표본주 착과 무게에 비대추정지수 곱하여 보정. 절반조사 시 추가 ×2.', '종합위험 수확감소보장', NULL, NULL, 'p.451', 451, 458, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-026', 'INVESTIGATION', '미보상비율 확인', '품목별 미보상비율 적용표 별표2에 따라 미보상비율 조사. 모든 수확량조사·과실손해조사·동상해조사의 마지막 단계 의무.', '공통', NULL, NULL, 'p.444', 444, 451, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-027', 'INVESTIGATION', '표본주 선정', '산정한 품종·수령별 표본주수 바탕으로 조사 대상주수 특성이 골고루 반영되도록 표본주 선정. 동일품종·동일수령이 아닌 경우 비례 분배. 표시리본 부착 의무.', '공통', NULL, NULL, 'p.439', 439, 446, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-028', 'INVESTIGATION', '표본주수 산정', '농지별 가입면적 또는 조사 대상주수 기준으로 별표1 품목별 표본주수표에 따라 산정. 적정 표본주수는 품종·수령별 조사 대상주수에 비례. 품종·수령별 적정표본주수 합 ≥ 전체 표본주수.', '공통', NULL, NULL, 'p.445', 445, 452, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-029', 'INVESTIGATION', '면적·재식간격 조사', 'GPS 면적측정기 또는 지형도 등 이용 보험 가입 면적과 실제 경작면적 비교. 재식면적 확인 (주간 길이 + 이랑 폭). 가입면적 대비 10% 이상 차이(혹은 1,000㎡ 초과) 시 계약 변경.', '공통', NULL, NULL, 'p.488', 488, 495, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-030', 'INVESTIGATION', '수확량조사 (밤·호두 변형)', '밤: 30mm 지름 규격대로 소과 분류 — 통과 과립은 80% 무게 적용. 호두: 품종별 청피 개수 + 무게 별도. 표본주별 수관면적 + 착과+낙과수 조사.', '종합위험 수확감소보장', NULL, NULL, 'p.440', 440, 447, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-031', 'INVESTIGATION', '수확량조사 (오미자)', '형태별·수령별 표본구간수 산정 → 유인틀 길이 방향 1m 단위 표본구간 선정. 표본구간 착과량 + 과중 조사. 다른 과수와 표본 단위가 본질 차이.', '종합위험 수확감소보장', NULL, NULL, 'p.456', 456, 463, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-032', 'INVESTIGATION', '비가림시설 손해조사', '포도·참다래·대추 적용. 피복재: 피해 면적 조사. 구조체: 손상된 골조 재사용 불가 시 교체 수량 + 비용 산정 / 재사용 가능 시 보수비 산정. 단지단위·1사고 단위 자기부담금 적용.', '비가림시설 손해보장', NULL, NULL, 'p.461', 461, 468, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-033', 'INVESTIGATION', '나무피해 확인', '품종·수령별 고사주수 (사과·배·단감·떫은감은 품종·재배방식·수령별). 보상하지 않는 손해로 고사한 나무 = 미보상주수. 미보상주수 + 수확불능나무 (사과·배·단감·떫은감) 별도. 나무에 표시 가능.', '공통', NULL, NULL, 'p.429', 429, 436, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-034', 'INVESTIGATION', '고사나무조사 (특약)', '나무손해보장 특약 가입 농지. 보장재해로 고사되거나 회생 불가능한 나무 수 조사. 수확완료 후 추가 고사나무 없으면 생략 가능. 전수조사 방법.', '나무손해보장', NULL, NULL, 'p.479', 479, 486, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-035', 'INVESTIGATION', '과실손해조사 (감귤 온주밀감)', '피해사실확인조사 시 과실손해조사가 필요하다고 판단된 과수원. 표본주 선정 (별표1) → 표본주별 전체 과실수 → 등급 내/외 분류 (30%/50%/80%/100%형) → 미보상비율.', '종합위험 과실손해보장', NULL, NULL, 'p.476', 476, 483, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-036', 'INVESTIGATION', '등급 내/외 피해과실 분류', '수확한 과실을 정상과실, 등급 내 피해과실, 등급 외 피해과실로 구분. 등급 내 = 30%형/50%형/80%형/100%형 (별표3 피해인정계수). 등급 외는 50% 가중치.', '종합위험 과실손해보장', NULL, NULL, 'p.477', 477, 484, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-037', 'INVESTIGATION', '동상해 과실손해조사', '감귤(온주밀감류) 수확기 동상해 피해 발생 시. 보장재해 여부 심사 → 표본조사. 동상해 80%형/100%형 과실수 별도 산정. 수확기잔존비율 = 사고발생 월(12월/1월/2월)별 사고발생일자 함수.', '수확개시 이후 동상해보장', NULL, NULL, 'p.478', 478, 485, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-038', 'INVESTIGATION', '꽃(눈) 피해조사 (블루베리)', '사고접수 농지 대상. 피해사실 확인조사 직후 또는 사고접수 직후. 꽃눈 고사율 + 꽃 고사율 → 최종 꽃 고사율 → 가중치 적용 → 최종 꽃 피해율 산출.', '종합위험 과실손해보장', NULL, NULL, 'p.474', 474, 481, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-039', 'INVESTIGATION', '경작불능조사 (복분자)', '피해사실 확인조사 시 경작불능조사 필요 판단 농지. 보험기간 = 계약체결일 24시~수확개시 시점(가입 이듬해 5월 31일 한도). 식물체 피해율 65% 이상 + 계약자 신청 시 경작불능보험금 지급 / 미만 또는 미신청 시 종합위험 과실손해조사.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.487', 487, 494, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('INV-040', 'INVESTIGATION', '식물체 피해율 65% 조사', '복분자 경작불능조사의 핵심 임계치. 식물체 피해율 ≥ 65% AND 계약자 신청 시 경작불능보험금 분기. 산지폐기 여부 확인 후 지급.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.488', 488, 495, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-021', 'CONCEPT', '피해율', '수확감소 보장 피해율 = (평년수확량-수확량-미보상감수량)÷평년수확량. 작물별 보정 (복숭아 병충해감수량 추가). 자기부담비율 초과 시 보험금 발생 조건.', '공통', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-022', 'CONCEPT', '자기부담비율', '보험 가입 시 선택한 비율. 피해율이 본 비율을 초과해야 보험금 발생. 감귤 온주밀감 나무손해 = 5% 고정.', '공통', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-023', 'CONCEPT', '자기부담금', '손해액 또는 보험가입금액 기반 산정. 비가림시설 = 손해액 10% (본체 30만~100만 / 피복재 10만~30만 한도). 감귤 온주밀감 = 보험가입금액 × 자기부담비율. 동상해 = |보험가입금액 × min(주계약피해율-자기부담비율, 0)|.', '공통', NULL, NULL, 'p.466', 466, 473, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-024', 'CONCEPT', '평년수확량', '보험 가입 직전 일정 기간 평균 수확량. 유자는 산출값 vs 최근 7년간 과거 수확량 올림픽 평균값 중 더 큰 값 적용. 피해율 분모.', '공통', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-025', 'CONCEPT', '수확량', '실제 조사된 수확량. 표본주 착과량 × 조사대상주수 + 미보상주수 × 주당 평년수확량 + 기수확량(수확 개시 후).', '공통', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-026', 'CONCEPT', '미보상감수량', '미보상감수량 = (평년수확량 - 수확량) × 미보상비율. 보장재해 외 감소량 차감 목적.', '공통', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-027', 'CONCEPT', '미보상비율', '품목별 미보상비율 적용표 별표2 기준. 보상하지 않는 손해 비율. 모든 피해율·감수량 산식에 곱연산 적용.', '공통', NULL, NULL, 'p.444', 444, 451, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-028', 'CONCEPT', '보험가입금액', '보험금 산정 기준 금액. 비가림시설 = 보험증권 기재 금액 한도. 손해액 산식 곱연산 인자.', '공통', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-029', 'CONCEPT', '손해액', '비가림시설: 재조달가액 기준 (수리·복구 미실시 시 시가 = 감가상각). 감귤 온주밀감: 보험가입금액 × 피해율. 동상해: {보험가입금액 - (보험가입금액×기사고피해율)} × 수확기잔존비율 × 동상해피해율 × (1-미보상비율).', '공통', NULL, NULL, 'p.465', 465, 472, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-030', 'CONCEPT', '재조달가액', '보험 목적과 동형·동질 신품 조달 비용. 비가림시설 손해액 산정 기준. 수리·복구 미실시 시 시가(감가상각) 적용 — 180일 이내 의사 통지 의무.', '비가림시설 손해보장', NULL, NULL, 'p.466', 466, 473, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-031', 'CONCEPT', '조사대상주수', '실제결과주수 - 수확완료주수 - 미보상주수 - 고사나무주수. 표본주 선정 + 표본주수 산정의 분모.', '공통', NULL, NULL, 'p.434', 434, 441, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-032', 'CONCEPT', '실제결과주수', '농지 내 품종·수령별 실제 식재된 결실 가능 나무 수. 사과·배·단감·떫은감은 품종·재배방식·수령별. 모든 주수 비율의 분모.', '공통', NULL, NULL, 'p.431', 431, 438, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-033', 'CONCEPT', '고사나무주수', '보장재해로 고사된 나무 + 회생 불가능 나무. 미보상고사주수와 분리. 나무손해보장특약 피해주수 분자.', '공통', NULL, NULL, 'p.429', 429, 436, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-034', 'CONCEPT', '미보상주수', '보상하지 않는 손해로 고사·피해를 입은 나무 + 보상하지 않는 재해로 수확불능 상태인 나무. 조사대상주수에서 제외.', '공통', NULL, NULL, 'p.429', 429, 436, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-035', 'CONCEPT', '수확불능주수', '사과·배·단감·떫은감 적용. 품종·재배방식·수령별 수확불능 상태 나무. 보상하지 않는 손해로 수확불능은 미보상주수로 분류.', '공통', NULL, NULL, 'p.430', 430, 437, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-036', 'CONCEPT', '표본주수', '품목별 표본주수표 별표1 기준 산정. 적정 표본주수 = 품종·수령별 조사 대상주수에 비례. 합 ≥ 전체 표본주수 의무.', '공통', NULL, NULL, 'p.445', 445, 452, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-037', 'CONCEPT', '표본구간', '오미자: 유인틀 길이 방향 1m. 복분자: 표본포기 전후 2포기씩 추가 5포기. 다른 과수 표본주와 다른 단위.', '공통', NULL, NULL, 'p.456', 456, 463, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-038', 'CONCEPT', '표본가지', '오디·블루베리 적용. 표본가지 결실수 합계 ÷ 표본가지 길이 합계 = 환산결실수. 블루베리 과실손해피해율 분모/분자에 사용.', '종합위험 과실손해보장', NULL, NULL, 'p.480', 480, 487, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-039', 'CONCEPT', '잔여수확량비율 (블루베리)', '수확개시 이전 = 1. 수확개시 이후 = 1 - {(사고일자 - 수확개시일자) ÷ 표준수확일수}. 표준수확일수 = 30일. 0보다 작을 수 없음.', '종합위험 과실손해보장', NULL, NULL, 'p.483', 483, 490, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-040', 'CONCEPT', '수확기잔존비율 (감귤 온주밀감)', '동상해 손해액 산식 인자. 12월=(100-39)-(0.935×사고발생일자), 1월=(100-68)-(0.774×사고발생일자), 2월=(100-92)-(0.286×사고발생일자). 단위는 %.', '수확개시 이후 동상해보장', NULL, NULL, 'p.484', 484, 491, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-041', 'CONCEPT', '기준과실수', '감귤 온주밀감 피해율 분모. 표본주의 과실수 총 합계. 동상해는 정상과실수 + 동상해피해 80%형 + 100%형 합.', '종합위험 과실손해보장', NULL, NULL, 'p.481', 481, 488, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-042', 'CONCEPT', '피해과실수', '등급 내 피해과실수 + (등급 외 피해과실수 × 50%). 등급 내 = 30%형×0.3 + 50%형×0.5 + 80%형×0.8 + 100%형×1.', '종합위험 과실손해보장', NULL, NULL, 'p.481', 481, 488, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-043', 'CONCEPT', '동상해피해율', '감귤 온주밀감 동상해 보장 특약 적용. 동상해 80%형 피해과실수 + 100%형 피해과실수 합 ÷ 기준과실수 (가중치 적용).', '수확개시 이후 동상해보장', NULL, NULL, 'p.484', 484, 491, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-044', 'CONCEPT', '기사고피해율', '동상해 손해액 산식 인자. 주계약피해율의 미보상비율을 반영하지 않은 값 + 이전 사고의 동상해 과실손해피해율 합산.', '수확개시 이후 동상해보장', NULL, NULL, 'p.484', 484, 491, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-045', 'CONCEPT', '주계약피해율', '감귤 온주밀감 과실손해보장 보통약관에서 산출한 피해율. 과실손해 추가보장 특약 보험금 분자.', '종합위험 과실손해보장', NULL, NULL, 'p.485', 485, 492, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-046', 'CONCEPT', '식물체 피해율 (복분자)', '복분자 경작불능 분기 임계치. ≥65% AND 계약자 신청 시 경작불능보험금. 미만 또는 미신청 시 종합위험 과실손해조사 진행.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.488', 488, 495, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-047', 'CONCEPT', '경작불능', '식물체 피해율 65% 이상 + 계약자 신청 시 분기. 산지폐기 여부 확인 후 경작불능보험금 지급. 종합위험 과실손해조사 대신 적용.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.488', 488, 495, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-048', 'CONCEPT', '환산결실수', '품종·수령별 표본가지 결실수 합계 ÷ 표본가지 길이 합계. 오디 조사결실수 산출의 단위 변환 핵심.', '종합위험 과실손해보장', NULL, NULL, 'p.480', 480, 487, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-049', 'CONCEPT', '조사결실수', '오디 피해율 산식 인자. 품종·수령별 환산결실수 × 조사대상주수 + 주당 평년결실수 × 미보상주수 ÷ 전체 실제결과주수.', '종합위험 과실손해보장', NULL, NULL, 'p.480', 480, 487, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-050', 'CONCEPT', '평년결실수', '오디 피해율 분모. 품종별 평년결실수를 실제결과주수로 나눈 값 = 주당 평년결실수.', '종합위험 과실손해보장', NULL, NULL, 'p.480', 480, 487, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('CONCEPT-051', 'CONCEPT', '미보상감수결실수', '평년결실수 - 조사결실수 값에 미보상비율 곱하여 산출. 0보다 작을 때는 0으로 처리.', '종합위험 과실손해보장', NULL, NULL, 'p.480', 480, 487, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-014', 'TERM', '정상과실', '피해인정계수 = 0. 별표3 등급 분류 시 기준 (피해 없음).', '공통', NULL, NULL, 'p.482', 482, 489, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-015', 'TERM', '30%형 피해과실', '피해인정계수 = 0.3. 별표3 적용. 피해과실수 산정 시 0.3 가중치 곱연산.', '공통', NULL, NULL, 'p.482', 482, 489, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-016', 'TERM', '50%형 피해과실', '피해인정계수 = 0.5. 복숭아 세균구멍병 피해 = 50%형으로 인정 (CONST-006).', '공통', NULL, NULL, 'p.482', 482, 489, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-017', 'TERM', '80%형 피해과실', '피해인정계수 = 0.8. 동상해 기준과실수 산정 시 정상과실 + 동상해 80%형 + 100%형 합 (감귤 온주밀감).', '공통', NULL, NULL, 'p.482', 482, 489, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-018', 'TERM', '100%형 피해과실', '피해인정계수 = 1.0. 별표3 등급 분류 최상위.', '공통', NULL, NULL, 'p.482', 482, 489, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-019', 'TERM', '결과지', '결실 가능한 가지. 무화과 수확시작 후 표본주의 고사·정상 결과지수 조사 단위.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.486', 486, 493, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-020', 'TERM', '결과모지', '결과지보다 1년 더 묵은 가지 (raw text 정의 정합 — p.490). 복분자 살아있는 결과모지수 조사 단위.', '수확전 종합위험 과실손해보장', NULL, NULL, 'p.490', 490, 497, '제2편 농작물재해보험 손해평가', '4. 수확전 종합위험 과실손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-021', 'TERM', '정아지수', '두릅 피해율 산정 단위. 피해 정아지수 ÷ 총 정아지수 = 피해 비율.', '종합위험 과실손해보장', NULL, NULL, 'p.482', 482, 489, '제2편 농작물재해보험 손해평가', '3. 종합위험 과실손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-022', 'TERM', '청피 (호두)', '호두 표본 단위 — 품종별 과실(청피) 개수 + 무게 별도 조사.', '종합위험 수확감소보장', NULL, NULL, 'p.440', 440, 447, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-023', 'TERM', '소과 (밤 30mm 미만)', '30mm 지름 규격대 통과 과립. 무게 80% 적용 (실제 무게 × 0.8) — F-22 / CONST-013, CONST-014.', '종합위험 수확감소보장', NULL, NULL, 'p.440', 440, 447, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 5, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('TERM-024', 'TERM', '비대추정지수 (매실)', '별표4 매실 비대추정지수표. 표본주 착과 무게 = 조사 착과량 × 비대추정지수 × 2(절반조사). 수확 시점 보정 인자.', '종합위험 수확감소보장', NULL, NULL, 'p.451', 451, 458, '제2편 농작물재해보험 손해평가', '2. 종합위험 수확감소보장방식 및 비가림과수 손해보장방식', 'BATCH-2', 2026, 6, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-005', 'LAW', '별표1 품목별 표본주수표', '표본주수 산정 기준. 가입면적 또는 조사대상주수 → 농지별 전체 표본주수. 복분자는 표본구간수표(별표1) 적용.', '공통', NULL, NULL, 'p.445', 445, 452, '별표', '별표1 품목별 표본주수표', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-006', 'LAW', '별표2 품목별 미보상비율 적용표', '미보상비율 산정 표. 품목별·재해유형별 차등. 모든 피해율 산식의 (1-미보상비율) 인자 결정.', '공통', NULL, NULL, 'p.444', 444, 451, '별표', '별표2 품목별 미보상비율 적용표', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-007', 'LAW', '별표3 과실 분류에 따른 피해인정계수', '정상 0 / 30%형 0.3 / 50%형 0.5 / 80%형 0.8 / 100%형 1.0. 모든 착과·낙과 피해 구성 조사 + 등급 분류 의무 기준.', '공통', NULL, NULL, 'p.482', 482, 489, '별표', '별표3 과실 분류에 따른 피해인정계수', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-008', 'LAW', '별표4 매실 비대추정지수', '매실 품종별 적정 수확 일자 + 조사 일자 + 비대추정지수. F-24 표본주 착과 무게 보정 인자.', '종합위험 수확감소보장', NULL, NULL, 'p.451', 451, 458, '별표', '별표4 매실 비대추정지수', 'BATCH-2', 2026, 8, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('LAW-009', 'LAW', '별표8 다른 보험 비례배분', '비가림시설 여러 보험 동시 가입 시 비례배분 산정. 보험가입금액 합계가 보험가액 초과 시 적용. 보험자 1인 청구 포기 영향 X.', '비가림시설 손해보장', NULL, NULL, 'p.466', 466, 473, '별표', '별표8 다른 보험 비례배분', 'BATCH-2', 2026, 7, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-14', 'FORMULA', '종합위험 수확감소보험금', 'F-14 종합위험 수확감소보험금 산식 노드. 16종 작물 수확감소 주계약. 보험금 = 보험가입금액 × (피해율 - 자기부담비율).', '종합위험', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-15', 'FORMULA', '수확감소 피해율', 'F-15 수확감소 피해율 산식 노드. 피해율 = (평년수확량 - 수확량 - 미보상감수량) ÷ 평년수확량. 자기부담비율 초과 시 지급.', '종합위험', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-16', 'FORMULA', '복숭아 피해율', 'F-16 복숭아 피해율 산식 노드. 복숭아 전용. 분자에 병충해감수량(세균구멍병 무게×0.5) 추가 반영.', '종합위험', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-17', 'FORMULA', '미보상감수량', 'F-17 미보상감수량 산식 노드. 미보상감수량 = (평년수확량 - 수확량) × 미보상비율.', '종합위험', NULL, NULL, 'p.464', 464, 471, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-18', 'FORMULA', '수확량감소 추가보장 특약 보험금', 'F-18 수확량감소 추가보장 특약 보험금 산식 노드. 포도·복숭아·감귤(만감류) 특약. 보험금 = 보험가입금액 × (피해율 × 10%).', '종합위험', NULL, NULL, 'p.465', 465, 472, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-19', 'FORMULA', '나무손해보장 특약 보험금', 'F-19 나무손해보장 특약 보험금 산식 노드. 보험금 = 보험가입금액 × (피해율 - 자기부담비율). 감귤 온주밀감 자기부담비율 5% 고정.', '종합위험', NULL, NULL, 'p.465', 465, 472, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-20', 'FORMULA', '나무손해 피해율', 'F-20 나무손해 피해율 산식 노드. 피해율 = 피해주수(고사된 나무, 미보상고사주수 제외) ÷ 실제결과주수.', '종합위험', NULL, NULL, 'p.465', 465, 472, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-21', 'FORMULA', '종합위험 비가림시설 보험금', 'F-21 종합위험 비가림시설 보험금 산식 노드. 포도·참다래·대추. 보험금 = MIN(손해액 - 자기부담금, 보험가입금액).', '종합위험', NULL, NULL, 'p.465', 465, 472, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-22', 'FORMULA', '품종별 개당 과중', 'F-22 품종별 개당 과중 산식 노드. 밤·호두 등 표본 보정. 분자에 정상표본무게합 + 소과(밤 30mm 미만) 무게×0.8.', '종합위험', NULL, NULL, 'p.440', 440, 447, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-23', 'FORMULA', '품종·수령별 주당 착과량', 'F-23 품종·수령별 주당 착과량 산식 노드. 주당 착과량 = 표본주의 착과 무게 ÷ 표본주수.', '종합위험', NULL, NULL, 'p.451', 451, 458, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-24', 'FORMULA', '표본주 착과 무게(매실 비대추정)', 'F-24 표본주 착과 무게(매실 비대추정) 산식 노드. 매실 적정 수확 일자 보정. 착과 무게 = 조사 착과량 × 비대추정지수 × 2(절반조사).', '종합위험', NULL, NULL, 'p.451', 451, 458, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-25', 'FORMULA', '과실손해보험금(오디)', 'F-25 과실손해보험금(오디) 산식 노드. 오디. 보험금 = 보험가입금액 × (피해율 - 자기부담비율). 결실수 기반 산식.', '종합위험', NULL, NULL, 'p.480', 480, 487, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-26', 'FORMULA', '오디 피해율', 'F-26 오디 피해율 산식 노드. 피해율 = (평년결실수 - 조사결실수 - 미보상감수결실수) ÷ 평년결실수.', '종합위험', NULL, NULL, 'p.480', 480, 487, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-27', 'FORMULA', '과실손해보험금(감귤 온주밀감)', 'F-27 과실손해보험금(감귤 온주밀감) 산식 노드. 감귤 온주밀감 손해액 기반. 보험금 = MAX(손해액 - 자기부담금, 0).', '종합위험', NULL, NULL, 'p.481', 481, 488, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-28', 'FORMULA', '감귤 온주밀감 피해율', 'F-28 감귤 온주밀감 피해율 산식 노드. 피해율 = (피해과실수 ÷ 기준과실수) × (1 - 미보상비율). 등급내+등급외×0.5.', '종합위험', NULL, NULL, 'p.481', 481, 488, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-29', 'FORMULA', '두릅 피해율', 'F-29 두릅 피해율 산식 노드. 피해율 = (피해 정아지수 ÷ 총 정아지수) × (1 - 미보상비율).', '종합위험', NULL, NULL, 'p.482', 482, 489, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-30', 'FORMULA', '블루베리 과실손해피해율', 'F-30 블루베리 과실손해피해율 산식 노드. 재배종별 가중. 고사주수 비율 + 표본가지 피해 비율 조합.', '종합위험', NULL, NULL, 'p.482', 482, 489, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-31', 'FORMULA', '블루베리 꽃 피해 시 종합 피해율', 'F-31 블루베리 꽃 피해 시 종합 피해율 산식 노드. 꽃 피해조사 + 과실손해 결합. 최종 꽃 피해율 + (1-최종꽃피해율)×F-30×(1-미보상비율).', '종합위험', NULL, NULL, 'p.482', 482, 489, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-32', 'FORMULA', '동상해 과실손해보험금(감귤 온주밀감)', 'F-32 동상해 과실손해보험금(감귤 온주밀감) 산식 노드. 동상해 손해액 = {보험가입금액-(보험가입금액×기사고피해율)}×수확기잔존비율×동상해피해율×(1-미보상비율).', '종합위험', NULL, NULL, 'p.484', 484, 491, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');
INSERT OR IGNORE INTO knowledge_nodes (id, type, name, description, lv1_insurance, lv2_crop, lv3_investigation, page_ref, book_page, pdf_page, chapter, section, batch_id, version_year, truth_weight, status) VALUES ('F-33', 'FORMULA', '과실손해 추가보장 특약 보험금(감귤 온주밀감)', 'F-33 과실손해 추가보장 특약 보험금(감귤 온주밀감) 산식 노드. 보험금 = 보험가입금액 × 주계약 피해율 × 10%.', '종합위험', NULL, NULL, 'p.485', 485, 492, '제2편 농작물재해보험 손해평가', '2~4. 종합위험 보장방식', 'BATCH-2', 2026, 9, 'draft');

-- 2. formulas (20 rows, INSERT OR IGNORE — 기존 등록 row 보존)
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-14', '종합위험 수확감소보험금', 'max(insurance_amount * (damage_rate - deductible_rate), 0)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율 number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.464', 'F-14', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-15', '수확감소 피해율', '(expected_yield - actual_yield - uncovered_loss) / expected_yield', '{"expected_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_loss":"미보상감수량 number>=0"}', 'p.464', 'F-15', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-16', '복숭아 피해율', '(expected_yield - actual_yield - uncovered_loss - pest_loss) / expected_yield', '{"expected_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_loss":"미보상감수량 number>=0","pest_loss":"병충해감수량(세균구멍병 무게×0.5) number>=0"}', 'p.464', 'F-16', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-17', '미보상감수량', '(expected_yield - actual_yield) * uncovered_rate', '{"expected_yield":"평년수확량 number>0","actual_yield":"수확량 number>=0","uncovered_rate":"미보상비율 number 0..1"}', 'p.464', 'F-17', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-18', '수확량감소 추가보장 특약 보험금', 'insurance_amount * damage_rate * 0.10', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율 number 0..1"}', 'p.465', 'F-18', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-19', '나무손해보장특약 보험금', 'max(insurance_amount * (damage_rate - deductible_rate), 0)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율(피해주수÷실제결과주수) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.465', 'F-19', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-20', '나무손해 피해율', 'dead_trees / actual_trees', '{"dead_trees":"피해주수(고사된 나무, 미보상고사주수 제외) number>=0","actual_trees":"실제결과주수 number>0"}', 'p.465', 'F-20', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-21', '종합위험 비가림시설보험금', 'min(loss_amount - deductible, insurance_amount)', '{"loss_amount":"손해액(재조달가액 기준) number>=0","deductible":"자기부담금(손해액×10%, 최소30만/최대100만, 피복재단독 최소10만/최대30만) number>=0","insurance_amount":"보험가입금액 number>=0"}', 'p.465', 'F-21', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-22', '품종별 개당 과중', '(normal_weight + small_weight * 0.8) / sample_count', '{"normal_weight":"품종별 정상표본과실무게합 number>=0","small_weight":"소과(밤 30mm 미만)표본과실무게합 number>=0","sample_count":"표본과실수 number>0"}', 'p.440', 'F-22', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-23', '품종·수령별 주당 착과량', 'sample_fruit_weight / sample_tree_count', '{"sample_fruit_weight":"품종·수령별 표본주의 착과 무게 number>=0","sample_tree_count":"표본주수 number>0"}', 'p.451', 'F-23', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-24', '표본주 착과 무게(매실 비대추정)', 'raw_weight * inflation_index * half_factor', '{"raw_weight":"조사 착과량 number>=0","inflation_index":"품종별 비대추정지수(매실, 별표4) number>0","half_factor":"절반조사시 2 / 전체조사시 1 number"}', 'p.451', 'F-24', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-25', '과실손해보험금(오디)', 'max(insurance_amount * (damage_rate - deductible_rate), 0)', '{"insurance_amount":"보험가입금액 number>=0","damage_rate":"피해율((평년결실수-조사결실수-미보상감수결실수)÷평년결실수) number 0..1","deductible_rate":"자기부담비율 number 0..1"}', 'p.480', 'F-25', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-26', '오디 피해율', '(expected_fruits - surveyed_fruits - uncovered_fruits) / expected_fruits', '{"expected_fruits":"평년결실수 number>0","surveyed_fruits":"조사결실수 number>=0","uncovered_fruits":"미보상감수결실수((평년결실수-조사결실수)×미보상비율, 0 미만 시 0) number>=0"}', 'p.480', 'F-26', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-27', '과실손해보험금(감귤 온주밀감)', 'max(loss_amount - deductible, 0)', '{"loss_amount":"손해액(보험가입금액×피해율) number>=0","deductible":"자기부담금(보험가입금액×자기부담비율) number>=0"}', 'p.481', 'F-27', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-28', '감귤 온주밀감 피해율', '(damaged_fruits / standard_fruits) * (1 - uncovered_rate)', '{"damaged_fruits":"피해과실수(등급내+등급외×0.5; 등급내=30%형×0.3+50%형×0.5+80%형×0.8+100%형×1) number>=0","standard_fruits":"기준과실수(표본주 과실수 총합계) number>0","uncovered_rate":"미보상비율 number 0..1"}', 'p.481', 'F-28', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-29', '두릅 피해율', '(damaged_buds / total_buds) * (1 - uncovered_rate)', '{"damaged_buds":"피해 정아지수 number>=0","total_buds":"총 정아지수 number>0","uncovered_rate":"미보상비율 number 0..1"}', 'p.482', 'F-29', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-30', '블루베리 과실손해피해율', '(dead_trees_ratio * residual_yield_ratio) + (survey_trees_ratio * (sample_damaged_fruits * residual_yield_ratio) / sample_total_fruits)', '{"dead_trees_ratio":"∑재배종별·수령별 고사주수÷실제결과주수 number 0..1","residual_yield_ratio":"재배종별 잔여수확량비율(수확개시이전=1, 수확개시이후=1-(사고일자-수확개시일자)÷30, 음수 시 0) number 0..1","survey_trees_ratio":"재배종별·수령별 조사대상주수÷실제결과주수 number 0..1","sample_damaged_fruits":"∑재배종별·수령별 표본가지 피해과실수 number>=0","sample_total_fruits":"∑재배종별·수령별 표본가지 전체 과실수 number>0"}', 'p.482', 'F-30', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-31', '블루베리 꽃 피해 시 종합 피해율', 'final_flower_damage + (1 - final_flower_damage) * fruit_damage_rate * (1 - uncovered_rate)', '{"final_flower_damage":"최종 꽃 피해율(=최종 꽃 고사율×가중치; 가중치는 최종꽃고사율 구간별 0~1.0 별표) number 0..1","fruit_damage_rate":"과실손해피해율(F-30) number 0..1","uncovered_rate":"미보상비율 number 0..1"}', 'p.482', 'F-31', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-32', '동상해 과실손해보험금(감귤 온주밀감)', 'max(loss_amount - deductible, 0)', '{"loss_amount":"손해액({보험가입금액-(보험가입금액×기사고피해율)}×수확기잔존비율×동상해피해율×(1-미보상비율)) number>=0","deductible":"자기부담금(|보험가입금액×min(주계약피해율-자기부담비율, 0)|) number>=0"}', 'p.484', 'F-32', 2026);
INSERT OR IGNORE INTO formulas (id, name, equation_template, variables_schema, page_ref, node_id, version_year) VALUES ('F-33', '과실손해 추가보장 특약 보험금(감귤 온주밀감)', 'insurance_amount * primary_damage_rate * 0.10', '{"insurance_amount":"보험가입금액 number>=0","primary_damage_rate":"주계약 피해율(과실손해보장 보통약관 산출값) number 0..1"}', 'p.485', 'F-33', 2026);

